std::vector<int> data = {10, 20, 30};

// Explicit type declaration (Read-only guarantee)
std::vector<int>::const_iterator cit;

// Traversal using cbegin() and cend()
for (cit = data.cbegin(); cit != data.cend(); ++cit) {
    int value = *cit;       // Access (Read allowed)

    // *cit = 50;          // Compile Error: Read-only access enforced
}

std::set<float> scores = {3.14f, 2.71f};
// Modern syntax using auto and cbegin()
for (auto it = scores.cbegin(); it != scores.cend(); ++it) {
    float f = *it;
}
